package dev.mfa.incident.notification.model;

import jakarta.persistence.Column;
import jakarta.persistence.Id;
import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.Version;
import java.time.Instant;
import java.util.UUID;
import org.hibernate.Hibernate;
import org.hibernate.annotations.CreationTimestamp;
import org.hibernate.annotations.UpdateTimestamp;
import org.hibernate.annotations.UuidGenerator;

/**
 * Columns shared by every table (P-0014). All four values are generated by Hibernate: the id
 * (UUIDv7), the timestamps (JVM clock, rounded to the column precision of microseconds) and the
 * version (optimistic locking). None can be set by application code.
 *
 * <p>Equality is row identity (P-0014): two instances are equal when they are of the same entity
 * class and have the same id. It is the only behaviour an entity has.
 */
@MappedSuperclass
public abstract class BaseEntity {

  @Id
  @UuidGenerator(style = UuidGenerator.Style.VERSION_7)
  @Column(name = "id", nullable = false, updatable = false)
  private UUID id;

  @CreationTimestamp
  @Column(name = "created_at", nullable = false, updatable = false)
  private Instant createdAt;

  @UpdateTimestamp
  @Column(name = "updated_at", nullable = false)
  private Instant updatedAt;

  @Version
  @Column(name = "version", nullable = false)
  private long version;

  public UUID getId() {
    return id;
  }

  public Instant getCreatedAt() {
    return createdAt;
  }

  public Instant getUpdatedAt() {
    return updatedAt;
  }

  public long getVersion() {
    return version;
  }

  /**
   * Same entity class, ignoring Hibernate proxies, and the same id. An entity without an id (not
   * persisted yet) equals only itself. Both ids are read through the getter: the method is final,
   * so on a proxy it runs on the proxy itself, whose own fields are empty.
   */
  @Override
  public final boolean equals(Object other) {
    if (this == other) {
      return true;
    }
    if (other == null || Hibernate.getClass(this) != Hibernate.getClass(other)) {
      return false;
    }
    UUID ownId = getId();
    return ownId != null && ownId.equals(((BaseEntity) other).getId());
  }

  /**
   * Constant per entity class, so it does not change when persisting assigns the id: an entity
   * added to a hash set before persist is still found after it.
   */
  @Override
  public final int hashCode() {
    return Hibernate.getClass(this).hashCode();
  }
}
